const dinoCards: CardDef[] = dinoList.map(([id, name, emoji, buzz, desc, f1, f2, f3, f4, fun]) => ({
  id,
  category: 'dinosaurs',
  name,
  difficulty: 'easy',
  emoji,
  buzzWords: buzz,
  clues: [
    desc,
    `Lived during the ${f1} with a ${f2} diet.`,
    `Physical dimensions: ${f3} with signature trait: ${f4}.`
  ],
  primaryClues: [desc, `Era: ${f1}.`],
  secondaryClues: [`Diet/Type: ${f2}.`, `Size: ${f3}.`],
  factGrid: [
    { icon: '⏳', label: 'Period / Era', value: f1 },
    { icon: '🥩', label: 'Diet / Ecology', value: f2 },
    { icon: '📏', label: 'Length / Weight', value: f3 },
    { icon: '🦴', label: 'Unique Trait', value: f4 }
  ],
  bonusTrivia: {
    question: `What geologic period did ${name} live in?`,
    answer: f1
  },
  facts: { isPrehistoric: true, fossilRecord: true },
  aliases: [name.toLowerCase()],
  explanation: `${name} is an extraordinary prehistoric organism preserved in the global fossil record.`,
  funFact: fun,
  verificationStatus: 'verified'
}));

writeCategory('dinosaurs.ts', 'DINOSAURS_CARDS', dinoCards);

